DELETE FROM `quest_offer_reward_locale` WHERE `ID` = 1390 AND `locale` = 'zhTW';
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES (1390,'zhTW','感謝你完成了這項工作！',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3550 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3550,'zhTW','以下詳細記錄了我們在洛克莫丹用來秘密存放情報、等候取件的所有地點。如果你能從探險者協會或他們的盟友那裡弄到任何文件，就把它們放在其中一個地點，我們的信使會在一週內取走包裹，送往我們的行動基地。$B$B一旦你把這本書裡的所有地點都記熟了，就把它燒掉，以免落入敵人之手。如果你有任何理由懷疑敵人已經對你的行動起了疑心，立刻把這本書燒掉。無論如何都不能讓它落入敵手，否則我們的通訊路線就會暴露。$B$B為了拉格納羅斯！',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3551 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3551,'zhTW','地點一：西洛克碼頭\\n\\r\\n\\r塞爾薩瑪東北方，有一間小屋和一座碼頭，矮人偶爾會在捕魚季節使用。把包裹裝進防水容器裡，藏在碼頭下方不易被發現的地方。$B$B在這個地點進行交接時，應僅限於夜間，以降低被當地漁民目擊的風險。基於顯而易見的原因，這個交接點在捕魚季節的優先度會降低。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3552 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3552,'zhTW','地點二：灰爪穴\\n\\r\\n\\r塞爾薩瑪南方有一座大山丘。山丘南側有一條小路通往山頂的洞穴。把包裹藏在洞穴後方的岩石後面。$B$B請不要繼續把這個洞穴當作棲身處或藏匿點使用。這麼做會危及我們包裹與信使路線的安全。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3553 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3553,'zhTW','地點三：山達的巢穴\\n\\r\\n\\r挖掘場西南方有一間簡陋的小屋，曾經是一位隱居者的住所。$B然而山達住進這個洞穴後，把所有可能的住客都嚇跑了。洞口外側正是絕佳的交接地點。$B$B提醒一下，山達是隻體型有兩個矮人大的巨型嗜殺蜘蛛。千萬不要把文件放進洞穴裡，就算她現在不在，遲早也會回來的。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3554 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3554,'zhTW','地點四：鐵鬚密室\\n\\r\\n\\r鐵鬚挖掘場中心的一條側通道，通往一處隱密——而且已經廢棄不用的壁龕。就藏在探險者協會的眼皮底下，是絕佳的交接地點。$B$B穴居人的出現分散了探險者協會的注意力，但別忘了他們對我們依然懷有敵意。夜間前往該地點時要多加小心，穴居人可能正埋伏著。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3555 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3555,'zhTW','地點五：摩格拉什骷髏神像\\n\\r\\n\\r這座石製骷髏神像看似屬於食人魔的地盤，但位置比食人魔實際活動範圍還要更南邊。把文件放在神像底座旁。$B$B切勿把文件放進骷髏神像的嘴裡。已經有好幾份文件因此永遠遺失，甚至還有一隻手，原因不明。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3556 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3556,'zhTW','地點六：湖心樹林\\n\\r\\n\\r洛克湖中央有一小片由三棵樹苗組成的樹林，是個相當隱密的交接地點。$B$B洛克湖的排水工程使這裡的隱密性略微降低，不過鱷魚倒是幫忙彌補了這一點。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3559 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3559,'zhTW','杜拉克，$B$B這名 $R 已經幫我收集到足夠的魔焰，可以對精靈發動攻擊了。$B$B這些拋射物將會造成毀滅性的打擊——但完全無法控制。我需要一個方法來引導它們的軌跡。$B$B等碎木崗哨獲救之後，我相信我插手惡魔之力的行為一定會被原諒的……$B$B卓卡',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3561 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3561,'zhTW','<藥劑師的筆記字跡潦草擁擠，複雜的煉金配方中夾雜著孩子氣塗鴉的骷髏頭和閃電圖案。瞇著眼睛，你勉強能辨認出最近一段文字的部分內容：>$B$B……最為壯麗的腐化，深深地嵌入活體組織之中。透過食物鏈傳播時<幾個字被抹糊了>，極具傳染性。今天的測試證實，它的來源只有部分屬於生物性。邪蹄，我那<難以辨認>的夥伴，一心只想著復仇，對牠身上更「具建設性」的用途視而不見<一大灘綠色的黏液污漬覆蓋了段落剩下的部分。>研究進展緩慢。希望我在阿薩萊克斯的夥伴們情況比較好。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3566 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3566,'zhTW','狰牙，$B$B我從碎木崗哨向你回報，消息不太樂觀。$B$B哨站最近遭到卡多雷的攻擊，導致所有回報都無法送出。$B$B圍攻雖已解除，但我們損失慘重，看來另一波攻勢即將來臨。$B$B只要命運允許，我們就會繼續把精靈送進墳墓。$B$B——卡卓克',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3567 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3567,'zhTW','<br /><br />緬懷</h1><br />沙爾丁、葛沙拉、沃爾科</h1>以及所有未能歸鄉的人們。</h1>',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3568 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3568,'zhTW','<這塊小小的墓碑上滿懷愛意地刻著獸人符文。><br /><br />$B$B$B$B$B——摯愛的歐格拉——<br />$B$B$B$B$B$B$B$B曼克里克之妻<br /><br />$B$B$B找了你好久好久<br />$B$B$B$B$B如今你已離去',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3570 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3570,'zhTW','第一天：\\r\\n\\r\\n登上了一艘名叫「卓卡之怒號」的船。$B我們正把特殊貨物運往大海另一端的遙遠之地。$B我的職責是在船上打掃，等靠岸之後負責偵察。\\r\\n\\r\\n總比在奧格瑪搜捕聯盟盜賊和德魯伊要好多了。\\r\\n\\r\\n食物沒有以前好吃，但烈酒的味道還是一樣。$B杜隆塔爾已經消失在視線之外了。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3571 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3571,'zhTW','第二天：\\r\\n\\r\\n食物和船身的搖晃讓我很不舒服！\\r\\n\\r\\n有好多兄弟都暈船了，要打掃的東西堆積如山。$B我覺得這不是個好主意，但如果他非去不可，我們也會心甘情願跟著他一路沉到海底。\\r\\n\\r\\n希望事情不會演變成那樣。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3572 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3572,'zhTW','第三天：\\r\\n\\r\\n海浪猛烈地拍打著船身。$B船長要我們把帆降下來。$B我們就像是被巨浪包圍的孩童玩具一樣。\\r\\n\\r\\n我或許不喜歡大海，但今天我像個真正的戰士一樣，把吃下去的東西都留在了肚子裡。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3573 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3573,'zhTW','第四天：\\r\\n\\r\\n地平線上出現了兩座小島。$B船長說我們只會從旁邊經過。$B他不想停下來。$B他的聲音裡帶著一種我不喜歡的緊繃感。$B聽起來像是恐懼。\\r\\n\\r\\n還有好多事要做……什麼？$B外面傳來爆炸聲。$B我要到甲板上去看看發生了什麼事。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3574 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3574,'zhTW','第？？天：\\r\\n\\r\\n我被沖上了一座島嶼的礁岸。$B這一定是我之前看到的兩座島之一。$B我的大多數兄弟都死了。$B我們的特殊貨物已經不見蹤影。$B我擔心最壞的情況，甚至不敢相信自己的想法。\\r\\n\\r\\n我不知道已經過了幾天。$B一天，也許兩天？$B肯定不會更多了。$B聯盟那些懦夫從兩座島中較大的一座後面偷襲了我們。$B他們人數太多了，不過我們可能擊沉了他們一艘船。\\r\\n\\r\\n我看到另一艘船直接衝進戰場，結果被撕成了碎片。$B我猜是地精。$B真是群蠢貨！',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3575 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3575,'zhTW','第？？加一天：\\r\\n\\r\\n我們在島頂搭起了一座臨時營地。$B阿格拉要我到西岸去尋找其他倖存者。$B基拉格則要帶一小隊人馬穿越島頂，搜尋聯盟的蹤跡。$B已經有幾個人向我們發動攻擊了。$B他們不會停下來，除非全部戰死。$B或是我們戰死。\\r\\n\\r\\n遠方傳來地精的聲音，我能看到他們船隻的殘骸。$B他們吵得很。$B我晚點再去觀察他們。$B首先，我發現了一個洞穴，裡面傳出動物和挖礦般的怪聲。\\r\\n\\r\\n我要去調查一下。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3576 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3576,'zhTW','敬啟：加吉泉夫人$B$B您要求的工業級瀉藥已隨信附上。對於布利莫·加吉泉先生遭遇懸崖巨人之後的下場，謹致哀悼之意。我很好奇您為何選擇用瀉藥來把他救回來，而不是某種催吐劑？在我看來，您這樣做對加吉泉先生實在有失公道。祝您好運！$B$B——洛麥克·齒輪帶',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3577 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3577,'zhTW','歡迎來到秘密實驗室，艾薩拉最引人入勝的新興觀光景點！<br /><br /><br />你是否曾經好奇過，秘密究竟是從哪裡來的？<br /><br /><br />在風景秀麗、資源豐饒的艾薩拉森林深處，地精科學家正埋首鑽研，為你發明明日的秘密，讓你今天就能盡情享受！只要付一筆小額的預付費用，你和全家人就能坐上最前排的座位，親眼見證技藝精湛的地精工程師探索、挑釁宇宙的根本結構。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3578 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3578,'zhTW','我們為何存在於此？是什麼讓我們擁有智慧？在達到臨界點、釋放出足以讓行星偏離自轉軸的衝擊波之前，我們究竟能把多少千弗拉普的不穩定能量，壓縮進一立方盎司危險易爆的火箭燃料裡？讓我們一起找出答案。你的秘密實驗室正等著你！<br /><br /><br /><小冊子剩下的36頁，全是複雜的法律免責聲明和禮品店訂購單。>',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3579 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3579,'zhTW','我們這些頭腦靈活、但身手不太靈活的人，必須找到……其他自保的方法。$B許多這樣的人選擇投身於魔法事業。$B$B$N，我一直在觀察你，你的頭腦就像個捕獸夾一樣敏銳。$B然而，要在這個動盪的時代裡活得好，像你這樣的人必須精通奧術。$B而要精通奧術，你就得來找我談談。$B$B到鐵砧堡來見我吧。$B我們有很多事情要討論。$B$B——提格里·梅羅維斯',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3580 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3580,'zhTW','謹記：薩滿絕不能強求力量，這麼做會激起元素的憤怒，而失去元素庇護的薩滿什麼都不是。$B追隨薩滿之道的人絕不能忘記這條最重要的信條。$B$B然而，能以敬重之心與元素攜手合作的薩滿，所掌握的力量少有人能及。$B如果你自認擁有這樣的謙遜，就到鐵砧堡來見我吧。$B我會教你——就像當年我的師父教我一樣——如何運用火、土、風、水與野性之力。$B$B~提歐·錘暴',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3581 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3581,'zhTW','「角色扮演」\\n\\n熟練的角色扮演技巧不可或缺。天才侏儒女孩才不會想要一個超級無聊的傢伙。用你們未來橫跨大陸的冒險故事來取悅她：\\n\\n$B「寶貝，你和我，我們要一起飛到卡林多，在泰達希爾的樹幹上刻下我們的名字，然後在安戈洛環形山的樹林間盪鞦韆度過餘生。」\\n\\n「說故事」\\n\\n分享你們一起共度的精彩未來吧！越是天馬行空越好。沒有什麼比一個雄心勃勃的計畫更能讓侏儒女孩興奮的了。這也是絕佳的話題開場白！\\n\\n$B「只要結合我們聰明的腦袋，我們就能奪回諾莫瑞根。……話說回來，我們到底為什麼還沒把諾莫瑞根奪回來？」',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3582 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3582,'zhTW','「調侃」\\n\\n調侃是一門用幽默的方式取笑女性的藝術。小心點，很容易就會玩過頭。叫她「地精殺手小蚊子」>只會讓你穿著剛買的綠色戈多克烈酒走路回家。試試更含蓄一點的招數吧。\\n\\n如果她表現得很孩子氣，一直不停地跳上酒吧裡的桌子，可以試試看：\\n\\n「我聽說暴風城孤兒院正在招募明星藝人喔。」\\n\\n如果她一直嘻笑著談論自己沒完沒了，可以試試看：\\n\\n「你的關機開關在哪裡？」\\n\\n重要提醒：侏儒女孩沒有關機開關。試圖尋找它可能會讓你賠上性命、肢體，或是荷包。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3583 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3583,'zhTW','你的品味比較獨特嗎？\\n你渴望的對象是否有點不屬於這個世界？\\n蹄子是你的菜，但魅魔又太超過了嗎？\\n\\n那就繼續看下去吧，我的朋友……',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3584 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3584,'zhTW','我才剛搭船抵達蔚藍海岸，就在路上攔下了一群年紀約230歲、正值青春年華的德萊尼女士。她們有說有笑，玩得十分盡興。運氣真好，還沒離開碼頭，我就找到了這趟旅程中正想認識的那種有趣、活力充沛的德萊尼女性。\\n\\n一開始我有點緊張，於是深吸一口氣，提醒自己：「她們同樣是在艾澤拉斯度假，想認識新朋友，好好玩一玩。」\\n\\n果然，她們在艾克索達見到像我這樣風流迷人的侏儒，也顯得十分開心。後來才發現，我們居然都住在光輝之殿附近。我們深情地互相凝視對方的雙眼，約好當晚稍晚再到阿達爾附近見面。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3585 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3585,'zhTW','隔天，我遇見了另一位美麗的德萊尼女性——她那對犄角的光澤，僅僅透露出她高雅品味的一絲端倪。我問她為什麼來艾克索達觀光，沒想到她驚訝地告訴我，她不是來觀光的——她就住在這裡。\\n\\n我先前對自己說過的話又浮現在腦海：\\n\\n「她是來度假的，想認識些出色的人，好好享受一番。」$B\\n我完全搞錯了，她根本不是來度假的！突然間，我腦中的齒輪喀嚓一聲轉了起來：$B我一直告訴自己，她們之所以這麼願意接受邀約，是因為她們在度假。這藉口簡直跟豬頭人一樣愚蠢！\\n\\n我是個有趣、風趣的傢伙，不管度不度假，任何頭腦清楚的女孩都會樂意跟我組隊！現在每當我遇見德萊尼女孩，我都會提醒自己這個簡單的道理：\\n\\n「她同樣也想認識新朋友，好好享受一番。」',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3586 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3586,'zhTW','這本辭典接下來的497頁，全都是用超級快照FX 2000相機拍攝的各種詭異角度照片。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3587 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3587,'zhTW','如何和矮人女性約會：\\n\\n一、請她請你喝一杯。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3588 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3588,'zhTW','老實說吧。自從第三次戰爭結束以來，暗夜精靈女孩什麼樣的搭訕台詞沒聽過。$B事實上，早在你我出生之前，她們就已經全都聽過一輪了。\\n\\n如果你想打動一位暗夜精靈女孩的心，你就得與眾不同。沒錯，我們都聽過暗夜精靈少女在信箱上跳舞、脫衣賺錢繳夜刃豹訓練費的傳聞。不管是真是假，如果你想讓那位可愛小姐的嘴角揚起微笑，你就得獨特、令人難忘，而且充滿自信。\\n\\n首先要表現出，你在乎的不只是外表。沒錯，她會蹦蹦跳跳，她會跳舞，但她能不能好好聊天呢？$B她懂不懂薩摩富蘭奇的正確用法？她知不知道怎麼玩得盡興？\\n\\n沒有什麼比帶一位暗夜精靈參加派對，卻只能看著她尷尬地獨自站在角落，開口就只會哀嘆她那位在遠古之戰中失去的高等精靈姊妹更糟糕的事了。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3589 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3589,'zhTW','沒有什麼比得上追求人類女孩的芳心。人類女孩無限包容、無比體貼，而且妙趣橫生，古往今來不知讓多少英雄為之傾倒。（詳見第三章：「吉安娜·普羅德摩爾與愛過她的男人們」）\\n\\n然而，一代又一代的經驗證明，光靠金錢、外貌或一身史詩級的鎧甲，是不足以吸引你夢想中的女人的。就連侏儒發明的力量在這裡也派不上用場。\\n\\n要真正打動對方的心，你應該具備以下特質。\\n\\n* 風趣友善\\n* 保持挑戰性\\n* 展現男子氣概\\n\\n',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3590 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3590,'zhTW','風趣友善\\n\\n有沒有那種一到你家就讓大家掃興的朋友？嗯，每個人身邊都有一個。他還會被邀請參加下一次派對嗎？除非他帶了麥酒來。如果你想成為一個有魅力的人，就過有魅力的生活。\\n\\n你會發現，你越樂於和別人交際，別人就越樂於和你交際！\\n\\n沒有什麼比帶著那種黏人、老是道歉的氛圍更快毀掉一個女孩夜晚心情的了。放下它，擁抱樂趣，你的自信就會隨之高漲。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3591 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3591,'zhTW','保持挑戰性\\n\\n現在有太多侏儒垂頭喪氣地從一間酒館晃到另一間酒館，絕望地抱著「絕不會有人類女孩想要我」這種畫地自限的想法。他們衝進酒館，對她大獻殷勤、猛請免費飲料，然後又垂頭喪氣地回家。\\n\\n好吧，讓我第一個告訴你，朋友，當你把自己賤價出賣時，你就是在貶低你那獨特而細膩的人格價值。社會一直告訴你，你不是獎品，女人永遠不會正眼看你，你必須乞求愛與關注。\\n\\n他們都錯了。不要這麼輕易地把感情送出去。與其問自己「她喜歡我嗎？」>不如反過來問自己「我喜歡她嗎？」>\\n\\n挑戰她——讓她知道你要找的女孩，不只是一張漂亮的臉蛋。如果她跟不上你的生活步調，那就放手。如果她展現出值得付出的一面，那麼一段美好的關係就此展開。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3592 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3592,'zhTW','展現男子氣概\\n\\n在這個我們被逐出家園、被迫為生存而戰、直面艾澤拉斯前所未見的恐怖事物的時代，你或許會以為，男子氣概的本質應該早已被人們充分理解了。\\n\\n可惜的是，陽剛之美的藝術早已失傳，被戰場上的浮華與榮光沖刷殆盡。然而，一切還沒有完全失去！只要透過練習與自信，你就能重新找回自己。\\n\\n一旦你遇見了夢想中的人類女孩，而她也證明了自己值得你付出感情：\\n\\n* 主動帶頭——向她展現你世界中一切美好的事物\\n* 牽起她的手——培養親密、深情的關係\\n* 展現尊重——尊重你自己、尊重她，也尊重周遭的世界\\n\\n最重要的是：\\n\\n* 負起責任\\n',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3593 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3593,'zhTW','疑難排解\\n\\n事情並非總是如你所預期的那樣發展，但這正是讓生活充滿未知與刺激的原因。不過，這裡有幾個小技巧，能大幅改善你的生活。以下是一些常見的失誤：\\n\\n* 不要死纏爛打\\n* 不要表現得太黏人\\n* 不要執著於不喜歡你的人\\n\\n這些問題都源自一個核心錯誤觀念：你一定要得到眼前正在交談的這位女性。放開心胸吧——這個美麗的世界裡還有許多女性，如果一段關係行不通，就放手吧。你會發現，你越不黏人，就越有魅力。\\n',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3594 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3594,'zhTW','<克羅高的字跡又大又歪七扭八，比小孩子亂塗鴉好不了多少。>$B$B希、希利……希利希德……<好幾個拼錯的字被劃掉了>是蟲子類的動物，不是蔬菜（至少不打一架是不會變成蔬菜的）。牠們住在地底下，不住地底下的時候除外。有些還會飛？（我猜的）。$B$B牠們吃起來真的超難吃。$B$B大部分希利希德都是蟲子的部件組成的。牠們的腿介於零條到八條左右（要看牠們是怎麼死的？）',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3595 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3595,'zhTW','燒牠們會讓牠們死掉。牠們有外殼（因為顯然是用卡拉做的，所以叫做&#65533卡拉殼片&#65533）沒有用力刺是刺不穿的。$B$B牠們挖洞挖得很快，但我不知道到底多快，因為牠們是在土裡挖洞的。$B$B希利希德的起源$B$B幾乎所有希利希德都是從洞裡冒出來的，通常是地上的洞。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3599 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3599,'zhTW','索瑞森皇帝，\\n$B$B以下是我在安戈洛環形山最近一次發現的報告。$B大災變發生後，我暫停了手邊的計畫，開始在環形山中搜尋新的潛在挖掘地點。$B奇怪的是，環形山受到大災變的衝擊並不嚴重，不過我確實在恐懼之徑的地面上，發現了一個看似巨獸下顎骨的東西！',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3600 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3600,'zhTW','這東西看起來像是這裡現存恐龍的祖先。$B過去幾週我一直在把它挖出來，這是我目前為止最令人興奮的一次挖掘。$B根據我的計算，這隻巨獸從頭到尾應該將近300英尺長。$B這比某些最大型的巨龍還要長，更是遠遠超過目前環形山裡任何一種恐龍的體型。',0);

DELETE FROM `page_text_locale` WHERE `ID` = 3601 AND `locale` = 'zhTW';
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES (3601,'zhTW','進度一直很緩慢，主要是因為我得隨時把身後的痕跡掩蓋掉。$B那個該死的地精，尼爾邁納，手下的爪牙還在這一帶挖掘，我可不能冒險讓這項發現的消息在我把最終結果送回黑石山脈之前洩漏出去。$B這或許正是能告訴我們泰坦當年在安戈洛究竟做了什麼的關鍵情報！$B$B謹上，$B$B杜林·凶鏟',0);
